"use server";

import { resend } from "@repo/email";
import ContactTemplate from "@repo/email/templates/contact";
import { parseError } from "@repo/observability/error";
import { headers } from "next/headers";
import { env } from "@/env";
import { clientIp, rateLimiter } from "@/lib/rate-limit";
import { parseContact } from "./schema";

interface ContactState {
  error?: string;
  success?: boolean;
}

// A person writes once, maybe twice with a correction. Three an hour per
// caller leaves room for that and not for a loop.
const PER_CALLER = { limit: 3, ms: 1000 * 60 * 60 };

const MESSAGES = {
  invalid: "Check the three fields: a name, an address that works, a message.",
  limited:
    "That inbox has heard from you a few times already. Try again in an hour.",
  sendFailed:
    "The message didn’t go out. Try again, or write to the address in the footer.",
};

export const contact = async (
  _prevState: ContactState,
  formData: FormData
): Promise<ContactState> => {
  const input = parseContact(formData);
  if (!input) {
    return { error: MESSAGES.invalid };
  }

  try {
    const ip = clientIp(await headers());
    if (ip) {
      const limiter = await rateLimiter("contact", PER_CALLER);
      const { success } = await limiter.limit(ip);
      if (!success) {
        return { error: MESSAGES.limited };
      }
    }

    const { error } = await resend.emails.send({
      from: env.RESEND_FROM,
      react: (
        <ContactTemplate
          email={input.email}
          message={input.message}
          name={input.name}
        />
      ),
      replyTo: input.email,
      subject: `Contact form: ${input.name}`,
      to: env.RESEND_FROM,
    });

    if (error) {
      // Logged and reported with the provider's wording; the visitor gets
      // a fixed line rather than an API message.
      parseError(error);
      return { error: MESSAGES.sendFailed };
    }

    return { success: true };
  } catch (error) {
    parseError(error);
    return { error: MESSAGES.sendFailed };
  }
};
=== SCHEMA ===
import { z } from "zod";

/**
 * What the contact form accepts. The caps are generous for a person and
 * tight for a script: a name fits on one line, a message fits in an inbox,
 * and the reply address has to be one Resend can set as Reply-To.
 */
export const contactSchema = z.object({
  email: z.string().trim().toLowerCase().max(254).pipe(z.email()),
  message: z.string().trim().min(1).max(5000),
  name: z.string().trim().min(1).max(120),
});

export type ContactInput = z.infer<typeof contactSchema>;

export function parseContact(formData: FormData): ContactInput | null {
  const result = contactSchema.safeParse({
    email: formData.get("email"),
    message: formData.get("message"),
    name: formData.get("name"),
  });
  return result.success ? result.data : null;
}
=== ASSETS ===
/**
 * Where email images are loaded from.
 *
 * An inbox fetches images on its own, long after the request that sent the
 * mail. That request's origin is only reachable from an inbox in production:
 * localhost is not, and preview deployments sit behind Vercel Authentication
 * (every host except the custom domains). The apex domain also 308s to www,
 * which not every client follows. So images always come from the canonical
 * public origin, whatever origin the signup arrived on.
 */
export const PUBLIC_ORIGIN = "https://www.hastoggle.dev";

export const assetUrl = (path: string) => `${PUBLIC_ORIGIN}/${path}`;
